<template>
  <div class="doc-edit-page">
    <header class="editor-toolbar">
      <div class="toolbar-left"><button class="btn btn-icon btn-ghost" type="button" title="返回" @click="router.push('/')"><ArrowLeft :size="19" /></button><input v-model="docTitle" class="title-input" maxlength="500" placeholder="无标题文档" @input="markLocalDraft" @blur="saveTitleIfChanged" @keydown.enter.prevent="$event.target.blur()" /></div>
      <div class="toolbar-center"><div v-if="onlineUsers.length" class="online-users"><span v-for="user in onlineUsers.slice(0,4)" :key="user.userId||user.id" class="user-avatar">{{ (user.username||user.name)?.charAt(0)?.toUpperCase() || '?' }}</span><small>{{ onlineUsers.length }} 人在线</small></div><span :class="['connection-dot',{offline:!connected}]"/><span class="save-status">{{ saveStatus }}</span><span>{{ wordCount }} 字</span></div>
      <div class="toolbar-right">
        <div v-if="!isCrdt" class="format-switch"><button :class="{active:contentFormat==='MARKDOWN'}" type="button" title="Markdown 编辑" @click="switchFormat('MARKDOWN')">MD</button><button :class="{active:contentFormat==='HTML'}" type="button" title="富文本编辑" @click="switchFormat('HTML')">富文本</button></div>
        <div v-if="!isCrdt&&contentFormat==='MARKDOWN'" class="view-switch"><button :class="{active:markdownView==='edit'}" type="button" title="纯编辑" @click="markdownView='edit'"><FilePenLine :size="16"/></button><button :class="{active:markdownView==='split'}" type="button" title="左右分栏" @click="markdownView='split'"><PanelsTopLeft :size="16"/></button><button :class="{active:markdownView==='preview'}" type="button" title="纯预览" @click="markdownView='preview'"><Eye :size="16"/></button></div>
        <button class="btn btn-icon btn-ghost" type="button" title="保存 Ctrl+S" @click="handleSave"><Save :size="17"/></button>
        <button :class="['btn btn-icon btn-ghost',{active:activePanel==='search'}]" type="button" title="搜索替换 Ctrl+F" @click="togglePanel('search')"><Search :size="17"/></button>
        <button :class="['btn btn-icon btn-ghost',{active:activePanel==='outline'}]" type="button" title="文档目录" @click="togglePanel('outline')"><ListTree :size="17"/></button>
        <button :class="['btn btn-icon btn-ghost',{active:activePanel==='attachments'}]" type="button" title="附件" @click="togglePanel('attachments')"><Paperclip :size="17"/></button>
        <button :class="['btn btn-icon btn-ghost',{active:activePanel==='comments'}]" type="button" title="批注" @click="togglePanel('comments')"><MessageSquareText :size="17"/></button>
        <button :class="['btn btn-icon btn-ghost',{active:activePanel==='versions'}]" type="button" title="版本历史" @click="togglePanel('versions')"><History :size="17"/></button><button v-if="isCrdt&&crdtAccess?.admin" :class="['btn btn-icon btn-ghost',{active:activePanel==='checkpoint'}]" type="button" title="协作恢复点" @click="togglePanel('checkpoint')"><DatabaseBackup :size="17"/></button>
        <button :class="['btn btn-icon btn-ghost',{active:activePanel==='export'}]" type="button" title="导出" @click="togglePanel('export')"><Download :size="17"/></button>
        <button :class="['btn btn-icon btn-ghost',{active:activePanel==='share'}]" type="button" title="分享" @click="togglePanel('share')"><Share2 :size="17"/></button>
        <button :class="['btn btn-icon btn-ghost',{active:activePanel==='people'}]" type="button" title="协作者" @click="togglePanel('people')"><Users :size="17"/></button>
        <button :class="['btn btn-icon btn-ghost',{active:activePanel==='settings'}]" type="button" title="文档设置" @click="togglePanel('settings')"><Info :size="17"/></button>
      </div>
    </header>

    <div v-if="!isCrdt&&conflict.active" class="conflict-bar"><AlertTriangle :size="18"/><span>检测到其他用户的新修改，本地草稿尚未覆盖服务器内容。</span><button type="button" @click="useRemoteVersion">加载最新版</button><button type="button" @click="retryLocalVersion">保留并重试本地稿</button></div>
    <div v-if="!connected" class="offline-bar"><img src="../assets/offline.svg" alt=""/><span>{{isCrdt?`协作连接已断开，本机有 ${crdtReliability.pending} 个待同步更新，正在第 ${Math.max(1,crdtReliability.reconnectAttempt)} 次重连（${crdtReliability.reconnectProgress}%）`:'连接已断开，本地草稿会继续保存，并在网络恢复后提交'}}</span><progress v-if="isCrdt" max="100" :value="crdtReliability.reconnectProgress"/></div>

    <div class="editor-body">
      <div class="editor-container" @dragover.prevent @drop.capture="handleEditorDrop" @paste.capture="handleEditorPaste">
        <CrdtRichTextEditor v-if="isCrdt&&crdtAccess" :key="docId" ref="crdtEditor" :doc-id="docId" :user="crdtUser" :editable="crdtAccess.writable" :commentable="crdtAccess.commentable" :comments-open="activePanel==='comments'" :page-settings="pageSettings" @status="handleCrdtStatus" @users="onlineUsers=$event" @change="handleCrdtChange" @upload-images="handleUploadImages" @add-comment="openCommentDialog" @comment-click="openCommentThread" @page-format-change="changePageFormat" @page-settings-change="savePageSettings"/>
        <MdEditor v-else-if="contentFormat==='MARKDOWN'" v-model="content" language="zh-CN" theme="light" :preview="markdownView!=='edit'" :previewOnly="markdownView==='preview'" :htmlPreview="false" :toolbarsExclude="['github']" style="height:100%" @onChange="handleContentChange" @onSave="handleSave" @onUploadImg="handleUploadImages"/>
        <RichTextEditor v-else v-model="content" @change="handleContentChange" @upload-images="handleUploadImages"/>
      </div>

      <div v-if="activePanel" class="panel-resizer" role="separator" aria-orientation="vertical" title="拖动调整侧栏宽度" @pointerdown="startPanelResize"></div><aside v-if="activePanel" class="side-panel" :style="{width:`${panelWidth}px`}"><header class="panel-header"><h2>{{ panelTitle }}</h2><button class="btn btn-icon btn-ghost" type="button" @click="activePanel='' "><X :size="18"/></button></header>
        <section v-if="activePanel==='checkpoint'" class="panel-content"><p class="panel-note">协作恢复点会整理已保存的实时编辑数据。需要时，可以将文档恢复到指定时间的状态。</p><div v-if="panelLoading" class="panel-state"><Loader2 :size="24" class="spin"/></div><template v-else><div class="checkpoint-status"><div><span>恢复点序号</span><strong>{{checkpointInfo.checkpointSequence??'-'}}</strong></div><div><span>已保存数据大小</span><strong>{{formatBytes(checkpointInfo.checkpointBytes||0)}}</strong></div><div><span>待整理的修改</span><strong>{{checkpointInfo.pendingUpdates||0}}</strong></div><div><span>待整理数据大小</span><strong>{{formatBytes(checkpointInfo.pendingBytes||0)}}</strong></div><div><span>最近创建时间</span><strong>{{formatDate(checkpointInfo.checkpointUpdatedAt)}}</strong></div></div><button class="btn btn-primary full-btn" type="button" :disabled="panelLoading" @click="createCheckpoint"><DatabaseBackup :size="16"/>立即创建恢复点</button><div class="checkpoint-history"><h3>可恢复的历史状态</h3><article v-for="item in checkpointHistory" :key="item.id"><div><strong>#{{item.checkpointSequence}}</strong><small>{{formatDate(item.createdAt)}} · {{formatBytes(item.snapshotBytes||0)}} · {{checkpointReason(item.reason)}}</small></div><button class="btn btn-secondary" type="button" @click="restoreCheckpoint(item)">恢复</button></article><p v-if="!checkpointHistory.length" class="panel-note">还没有历史恢复点。创建新恢复点后，系统会保留之前的文档状态。</p></div></template></section>
        <section v-else-if="activePanel==='outline'" class="panel-content outline-list"><div v-for="(item,index) in outline" :key="index" :style="{paddingLeft:`${(item.level-1)*14}px`}"><button type="button" @click="scrollToHeading(index)">{{ item.text }}</button><button v-if="isCrdt&&crdtAccess?.writable" class="outline-fold" type="button" :title="item.collapsed?'展开标题内容':'折叠标题内容'" @click="toggleOutlineHeading(index)">{{item.collapsed?'＋':'−'}}</button></div><div v-if="!outline.length" class="panel-state">暂无标题目录</div></section>
        <section v-else-if="activePanel==='search'" class="panel-content form-stack"><label>查找<input v-model="searchForm.query" class="input" autofocus @keydown.enter.prevent="replaceOne"/></label><label>替换为<input v-model="searchForm.replacement" class="input"/></label><p class="panel-note">找到 {{ matchCount }} 处匹配</p><div class="button-row"><button class="btn btn-secondary" type="button" @click="replaceOne">替换一处</button><button class="btn btn-primary" type="button" @click="replaceAll">全部替换</button></div></section>
        <section v-else-if="activePanel==='attachments'" class="panel-content"><input ref="attachmentInput" class="hidden-input" type="file" multiple @change="uploadAttachments"/><button class="btn btn-primary full-btn" type="button" @click="attachmentInput?.click()"><Upload :size="16"/>上传附件</button><div v-if="panelLoading" class="panel-state"><Loader2 :size="22" class="spin"/></div><div v-else class="attachment-list"><article v-for="item in attachments" :key="item.id"><Paperclip :size="16"/><div><a :href="item.fileUrl" target="_blank" rel="noopener">{{ item.originalName }}</a><small>{{ formatBytes(item.fileSize) }}</small></div><button type="button" title="删除" @click="removeAttachment(item)"><Trash2 :size="15"/></button></article><div v-if="!attachments.length" class="panel-state">暂无附件</div></div></section>
        <section v-else-if="activePanel==='versions'" class="panel-content"><div class="panel-actions"><button class="btn btn-primary btn-sm" type="button" @click="handleSaveVersion"><Save :size="14"/>保存版本</button><button class="btn btn-ghost btn-sm danger-text" type="button" @click="handleDeleteVersions"><Trash2 :size="14"/>清空</button></div><p v-if="compareSelection.length===1" class="panel-note">已选择 v{{compareSelection[0].versionNum}}，再选一个版本进行对比</p><div v-if="panelLoading" class="panel-state"><Loader2 :size="24" class="spin"/></div><div v-else-if="versions.length" class="version-list"><article v-for="version in versions" :key="version.id" class="version-item"><div><strong>{{version.versionName||`v${version.versionNum}`}}</strong><span class="version-tag">{{versionLabel(version.versionType)}}</span></div><p v-if="version.description">{{version.description}}</p><time>v{{version.versionNum}} · {{formatTime(version.createdAt)}}</time><footer><button type="button" @click="compareVersion(version)">对比</button><button type="button" @click="previewVersion(version)">预览</button><button type="button" @click="rollbackVersion(version)">回滚</button></footer></article></div><div v-else class="panel-state">暂无版本记录</div></section>
        <section v-else-if="activePanel==='comments'" class="panel-content"><div class="comment-tools"><select v-model="commentFilter" class="input"><option value="OPEN">未解决</option><option value="ALL">全部</option><option value="RESOLVED">已解决</option></select><button v-if="selectedCommentIds.length&&crdtAccess?.writable" class="btn btn-secondary btn-sm" type="button" @click="resolveSelectedComments">批量解决</button></div><div v-if="panelLoading" class="panel-state"><Loader2 :size="24" class="spin"/></div><div v-else class="comment-list"><article v-for="thread in commentThreads" :key="thread.id" :data-comment-thread-id="thread.id" :class="{resolved:thread.status==='RESOLVED',active:activeCommentId===thread.id}" @click="activateCommentThread(thread)"><header><label @click.stop><input v-if="crdtAccess?.writable" type="checkbox" :value="thread.id" v-model="selectedCommentIds"/></label><strong>{{thread.authorName||`用户 ${thread.userId}`}}</strong><time>{{formatTime(thread.createdAt)}}</time></header><blockquote v-if="thread.selectedText">{{thread.selectedText}}</blockquote><p>{{thread.content}}</p><div v-if="thread.replies?.length" class="comment-replies"><div v-for="reply in thread.replies" :key="reply.id"><strong>{{reply.authorName||`用户 ${reply.userId}`}}</strong><p>{{reply.content}}</p><time>{{formatTime(reply.createdAt)}}</time></div></div><footer><button v-if="crdtAccess?.commentable" type="button" @click.stop="replyComment(thread)">回复</button><button v-if="crdtAccess?.writable" type="button" @click.stop="toggleCommentStatus(thread)">{{thread.status==='RESOLVED'?'重新打开':'解决'}}</button><button class="danger-text" type="button" @click.stop="removeComment(thread)">删除</button></footer></article><div v-if="!commentThreads.length" class="panel-state">当前筛选下没有批注</div></div></section>
        <section v-else-if="activePanel==='export'" class="panel-content export-list"><p class="panel-note">导出使用当前编辑器中的实时内容。</p><button class="btn btn-secondary" type="button" @click="exportDocument('docx')"><Download :size="16"/>Word 文档 (.docx)</button><button class="btn btn-secondary" type="button" @click="exportDocument('pdf')"><Download :size="16"/>服务端 PDF (.pdf)</button><button class="btn btn-secondary" type="button" @click="exportDocument('html')"><Download :size="16"/>离线网页 (.html)</button><button class="btn btn-secondary" type="button" @click="exportDocument('markdown')"><Download :size="16"/>Markdown (.md)</button><button class="btn btn-secondary" type="button" @click="exportDocument('txt')"><Download :size="16"/>纯文本 (.txt)</button><button class="btn btn-primary" type="button" @click="openPrintPreview"><Printer :size="16"/>打印预览</button></section>
        <section v-else-if="activePanel==='share'" class="panel-content form-stack"><label>访问权限<select v-model="shareForm.permission" class="input"><option value="READ">只读</option></select></label><label>访问密码<input v-model.trim="shareForm.password" class="input" maxlength="255" placeholder="留空表示无需密码"/></label><label>失效时间<input v-model="shareForm.expireTime" class="input" type="datetime-local"/></label><button class="btn btn-primary" type="button" @click="createShare"><Link :size="16"/>生成分享链接</button><div v-if="shareLink" class="share-result"><input :value="shareLink" class="input" readonly/><button class="btn btn-secondary" type="button" @click="copyShareLink"><Copy :size="15"/>复制</button></div></section>
        <section v-else-if="activePanel==='people'" class="panel-content"><form class="collaborator-form" @submit.prevent="addCollaborator"><input v-model.trim="collaboratorForm.username" class="input" placeholder="协作者用户名" required/><select v-model="collaboratorForm.permission" class="input"><option value="READ">只读</option><option value="COMMENT">仅批注</option><option value="WRITE">编辑</option><option value="ADMIN">管理</option></select><button class="btn btn-primary btn-icon" type="submit"><UserPlus :size="17"/></button></form><div class="collaborator-list"><article v-for="person in collaborators" :key="person.userId"><div class="person-avatar">{{person.username?.charAt(0)?.toUpperCase()}}</div><div class="person-info"><strong>{{person.username}}</strong><small>{{person.email||`用户 ${person.userId}`}}</small></div><select :value="person.permission" @change="updateCollaborator(person,$event.target.value)"><option value="READ">只读</option><option value="COMMENT">仅批注</option><option value="WRITE">编辑</option><option value="ADMIN">管理</option></select><button type="button" @click="removeCollaborator(person)"><X :size="15"/></button></article></div></section>
        <section v-else class="panel-content form-stack"><label>分类<input v-model.trim="metadata.category" class="input" maxlength="100" placeholder="例如：工作、学习"/></label><label>标签<input v-model.trim="metadata.tags" class="input" placeholder="多个标签用逗号分隔"/></label><p class="panel-note">纸张、页边距、页眉和页脚已移到编辑器上方的页面设置按钮。</p><button class="btn btn-primary" type="button" @click="saveMetadata">保存文档信息</button><button class="btn btn-secondary" type="button" @click="saveAsTemplate">保存为模板</button><div class="feedback-entry"><div><MessageSquareWarning :size="18"/><span><strong>遇到问题？</strong><small>反馈会自动关联当前文档，可附加问题截图。</small></span></div><button class="btn btn-secondary btn-sm" type="button" @click="feedbackOpen=true">问题反馈</button></div><div class="settings-list"><div><span>协作模式</span><strong>{{isCrdt?'Yjs CRDT':'LEGACY'}}</strong></div><div><span>内容格式</span><strong>{{contentFormat==='HTML'?'富文本':'Markdown'}}</strong></div><div><span>文档 ID</span><strong>{{docId}}</strong></div><div v-if="!isCrdt"><span>修订号</span><strong>{{revision}}</strong></div><div><span>创建时间</span><strong>{{formatDate(docData?.createdAt)}}</strong></div><div><span>最后更新</span><strong>{{formatDate(docData?.updatedAt)}}</strong></div></div></section>
      </aside>
    </div>
    <div v-if="preview.open" class="modal-backdrop" @click.self="preview.open=false"><div class="preview-modal"><header><div><strong>版本 v{{preview.version?.versionNum}}</strong><span>{{formatDate(preview.version?.createdAt)}}</span></div><button class="btn btn-icon btn-ghost" type="button" @click="preview.open=false"><X :size="18"/></button></header><div v-if="preview.version?.contentFormat==='HTML'" class="rich-version-preview" v-html="safeVersionHtml"></div><MdPreview v-else :modelValue="preview.version?.content||''" language="zh-CN"/></div></div>
    <div v-if="comparison.open" class="modal-backdrop" @click.self="comparison.open=false"><div class="preview-modal compare-modal"><header><strong>{{comparison.title}}</strong><button class="btn btn-icon btn-ghost" type="button" @click="comparison.open=false"><X :size="18"/></button></header><div class="diff-view"><div class="diff-head"><strong>{{comparison.olderLabel}}</strong><strong>{{comparison.newerLabel}}</strong></div><div v-for="(row,index) in comparison.rows" :key="index" class="diff-row"><div :class="{'diff-remove':row.type==='removed'||row.type==='changed'}"><span class="diff-line-number">{{row.oldNumber||''}}</span><code><template v-for="(part,partIndex) in row.oldParts" :key="partIndex"><mark v-if="part.changed">{{part.text}}</mark><span v-else>{{part.text}}</span></template></code></div><div :class="{'diff-add':row.type==='added'||row.type==='changed'}"><span class="diff-line-number">{{row.newNumber||''}}</span><code><template v-for="(part,partIndex) in row.newParts" :key="partIndex"><mark v-if="part.changed">{{part.text}}</mark><span v-else>{{part.text}}</span></template></code></div></div></div></div></div>
    <div v-if="printPreview.open" class="modal-backdrop" @click.self="printPreview.open=false"><div class="print-modal"><header><strong>打印预览</strong><div><button class="btn btn-primary btn-sm" type="button" @click="printPreviewFrame"><Printer :size="15"/>打印</button><button class="btn btn-icon btn-ghost" type="button" @click="printPreview.open=false"><X :size="18"/></button></div></header><iframe ref="printFrame" title="打印预览" :srcdoc="printPreview.html"/></div></div>
    <div v-if="commentDialog.open" class="modal-backdrop" @click.self="closeCommentDialog"><form class="comment-dialog" @submit.prevent="submitCommentDialog"><header><strong>{{commentDialog.parentId?'回复批注':'添加批注'}}</strong><button class="btn btn-icon btn-ghost" type="button" @click="closeCommentDialog"><X :size="18"/></button></header><blockquote v-if="commentDialog.selectedText">{{commentDialog.selectedText}}</blockquote><label>批注内容<textarea v-model.trim="commentDialog.content" rows="5" autofocus :placeholder="commentDialog.parentId?'可使用 @用户名 提及协作者':'输入批注内容'"></textarea></label><footer><button class="btn btn-secondary" type="button" @click="closeCommentDialog">取消</button><button class="btn btn-primary" type="submit" :disabled="!commentDialog.content">{{commentDialog.parentId?'回复':'添加'}}</button></footer></form></div>
    <div v-if="deleteCommentDialog.open" class="modal-backdrop" @click.self="closeDeleteCommentDialog"><section class="comment-dialog confirm-comment-dialog"><header><strong>删除批注</strong><button class="btn btn-icon btn-ghost" type="button" @click="closeDeleteCommentDialog"><X :size="18"/></button></header><p>确定删除这条批注及其全部回复吗？删除后无法恢复。</p><footer><button class="btn btn-secondary" type="button" @click="closeDeleteCommentDialog">取消</button><button class="btn btn-primary danger-button" type="button" :disabled="deleteCommentDialog.busy" @click="confirmRemoveComment">{{deleteCommentDialog.busy?'删除中…':'删除'}}</button></footer></section></div>
    <FeedbackDialog :open="feedbackOpen" :doc-id="docId" @close="feedbackOpen=false" />
  </div>
</template>

<script setup>
import { computed, defineAsyncComponent, nextTick, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router'
import { MdEditor, MdPreview } from 'md-editor-v3'; import 'md-editor-v3/lib/style.css'
import { htmlToMarkdown, markdownToHtml, sanitizeHtml } from '../utils/contentConversion'
import { AlertTriangle, ArrowLeft, Copy, DatabaseBackup, Download, Eye, FilePenLine, History, Info, Link, ListTree, Loader2, MessageSquareText, MessageSquareWarning, PanelsTopLeft, Paperclip, Printer, Save, Search, Share2, Trash2, Upload, UserPlus, Users, X } from 'lucide-vue-next'
import dayjs from 'dayjs'; import relativeTime from 'dayjs/plugin/relativeTime'; import 'dayjs/locale/zh-cn'
import { attachmentApi, commentApi, crdtApi, docApi, fileApi, permissionApi, shareApi, tagApi, templateApi, versionApi } from '../api'
import { CollabWebSocket } from '../utils/websocket'; import { error, success, warning } from '../utils/toast'
import { confirmDialog, promptDialog } from '../utils/dialog'
import { getRealtimeAccessToken } from '../api'
import { useDocStore } from '../store'

dayjs.extend(relativeTime); dayjs.locale('zh-cn')
const RichTextEditor = defineAsyncComponent(() => import('../components/RichTextEditor.vue'))
const CrdtRichTextEditor = defineAsyncComponent(() => import('../components/CrdtRichTextEditor.vue'))
const FeedbackDialog = defineAsyncComponent(() => import('../components/FeedbackDialog.vue'))
const route=useRoute(),router=useRouter(),docStore=useDocStore(),docId=computed(()=>Number(route.params.id)); const docData=ref(null),docTitle=ref(''),content=ref(''),contentFormat=ref('MARKDOWN'),markdownView=ref('split'),revision=ref(0),acceptedTitle=ref(''),acceptedContent=ref(''),acceptedFormat=ref('MARKDOWN')
const connected=ref(false),saveStatus=ref(''),onlineUsers=ref([]),activePanel=ref(''),panelLoading=ref(false),versions=ref([]),comments=ref([]),collaborators=ref([]),attachments=ref([]),shareLink=ref(''),attachmentInput=ref(null),crdtAccess=ref(null),crdtEditor=ref(null)
const shareForm=reactive({permission:'READ',password:'',expireTime:''}),collaboratorForm=reactive({username:'',permission:'WRITE'}),preview=reactive({open:false,version:null}),conflict=reactive({active:false,localContent:'',localTitle:'',remote:null}),searchForm=reactive({query:'',replacement:''}),metadata=reactive({category:'',tags:''})
const pageSettings=reactive({pageFormat:'A4',marginTop:20,marginRight:20,marginBottom:20,marginLeft:20,pageHeader:'',pageFooter:''})
const crdtReliability=reactive({pending:0,reconnectAttempt:0,reconnectProgress:0}),checkpointInfo=reactive({}),checkpointHistory=ref([])
const commentFilter=ref('OPEN'),selectedCommentIds=ref([]),compareSelection=ref([]),comparison=reactive({open:false,title:'',olderLabel:'较早版本',newerLabel:'较新版本',rows:[]}),printPreview=reactive({open:false,html:''}),printFrame=ref(null)
const panelWidth=ref(280),commentDialog=reactive({open:false,parentId:null,selectedText:'',content:''})
const activeCommentId=ref(null),deleteCommentDialog=reactive({open:false,item:null,busy:false})
const feedbackOpen=ref(false)
const panelTitle=computed(()=>({outline:'文档目录',search:'搜索与替换',attachments:'附件',comments:'批注',versions:'版本历史',checkpoint:'协作恢复点',export:'导出文档',share:'分享文档',people:'协作者',settings:'文档设置'}[activePanel.value]||''))
const wordCount=computed(()=>{const text=contentFormat.value==='HTML'?new DOMParser().parseFromString(content.value,'text/html').body.textContent||'':content.value;return text.replace(/\s/g,'').length})
const outline=computed(()=>{if(contentFormat.value==='MARKDOWN')return content.value.split('\n').map(line=>{const match=line.match(/^(#{1,6})\s+(.+)/);return match?{level:match[1].length,text:match[2],collapsed:false}:null}).filter(Boolean);const document=new DOMParser().parseFromString(content.value,'text/html');return [...document.querySelectorAll('h1,h2,h3,h4,h5,h6')].map(node=>({level:Number(node.tagName[1]),text:node.textContent,collapsed:node.dataset.collapsed==='true'}))})
const isCrdt=computed(()=>docData.value?.collabMode==='CRDT')
const crdtUser=computed(()=>({id:crdtAccess.value?.userId,name:crdtAccess.value?.displayName||'协作者',avatar:crdtAccess.value?.avatar,color:`hsl(${Number(crdtAccess.value?.userId||1)*47%360} 65% 48%)`}))
const matchCount=computed(()=>searchForm.query?content.value.split(searchForm.query).length-1:0); const hasUnsaved=computed(()=>docTitle.value!==acceptedTitle.value||(!isCrdt.value&&(content.value!==acceptedContent.value||contentFormat.value!==acceptedFormat.value)))
const safeVersionHtml=computed(()=>sanitizeHtml(preview.version?.content||''))
const commentThreads=computed(()=>comments.value.filter(item=>!item.parentId&&(
  commentFilter.value==='ALL'||item.status===commentFilter.value)).map(root=>({
    ...root,replies:comments.value.filter(item=>item.parentId===root.id).sort((a,b)=>new Date(a.createdAt)-new Date(b.createdAt))
  })))
let socket,changeTimer,applyingRemote=false,editorReady=false,panelResizeHandler,panelResizeEndHandler

onMounted(async()=>{window.addEventListener('keydown',handleShortcut);window.addEventListener('beforeunload',handleBeforeUnload);if(await loadDoc()&&!isCrdt.value)connectWebSocket()})
onUnmounted(()=>{clearTimeout(changeTimer);socket?.disconnect();stopPanelResize();window.removeEventListener('keydown',handleShortcut);window.removeEventListener('beforeunload',handleBeforeUnload)})
onBeforeRouteLeave(async()=>!hasUnsaved.value||await confirmDialog('文档还有未保存的修改，离开后可能会丢失。', { title: '离开当前文档', confirmText: '仍然离开', danger: true }))
watch(()=>route.params.id,async()=>{clearTimeout(changeTimer);socket?.disconnect();activePanel.value='';if(await loadDoc()&&!isCrdt.value)connectWebSocket()})
watch(activePanel,value=>{if(value==='versions')loadVersions();if(value==='comments')loadComments();if(value==='people')loadCollaborators();if(value==='attachments')loadAttachments();if(value==='checkpoint')loadCheckpoint();if(value==='settings')loadTags()})

async function loadDoc(){editorReady=false;crdtAccess.value=null;connected.value=false;try{const response=await docApi.detail(docId.value);applyDocument(response.data);if(isCrdt.value){const access=await crdtApi.access(docId.value);crdtAccess.value=access.data;contentFormat.value='HTML';saveStatus.value='连接中'}else{const draft=readDraft();if(draft&&draft.content!==content.value&&await confirmDialog('检测到一份未上传的本地草稿，是否恢复？',{title:'恢复本地草稿',confirmText:'恢复草稿'})){docTitle.value=draft.title;content.value=draft.content;contentFormat.value=draft.format||'MARKDOWN';saveStatus.value='已恢复草稿'}}await nextTick();editorReady=true;return true}catch(exception){error(exception.message||'文档加载失败');router.push('/');return false}}
function applyDocument(document){applyingRemote=true;docData.value=document;docTitle.value=document.title||'';contentFormat.value=document.contentFormat||'MARKDOWN';content.value=contentFormat.value==='HTML'?sanitizeHtml(document.content||''):document.content||'';revision.value=document.revision||0;acceptedTitle.value=docTitle.value;acceptedContent.value=content.value;acceptedFormat.value=contentFormat.value;metadata.category=document.category||'';Object.assign(pageSettings,{pageFormat:document.pageFormat||'A4',marginTop:document.marginTop??20,marginRight:document.marginRight??20,marginBottom:document.marginBottom??20,marginLeft:document.marginLeft??20,pageHeader:document.pageHeader||'',pageFooter:document.pageFooter||''});nextTick(()=>applyingRemote=false)}
async function connectWebSocket(){if(isCrdt.value)return;const token=await getRealtimeAccessToken();socket=new CollabWebSocket(docId.value,token);socket.on('connected',()=>{connected.value=true;saveStatus.value='已连接'});socket.on('disconnected',()=>{connected.value=false;saveStatus.value='离线'});socket.on('onlineUsers',message=>onlineUsers.value=message.data?.users||[]);socket.on('documentUpdate',message=>{applyingRemote=true;if(message.data?.title!==undefined)docTitle.value=message.data.title;if(message.data?.content!==undefined)content.value=message.data.content;revision.value=message.data?.revision??revision.value;acceptedTitle.value=docTitle.value;acceptedContent.value=content.value;saveStatus.value='已同步';clearDraft();nextTick(()=>applyingRemote=false)});socket.on('revisionConflict',prepareConflict);socket.connect()}
function markLocalDraft(){if(!editorReady||applyingRemote||isCrdt.value)return;localStorage.setItem(draftKey(),JSON.stringify({title:docTitle.value,content:content.value,format:contentFormat.value,revision:revision.value,time:Date.now()}))}
function handleContentChange(){if(isCrdt.value||!editorReady||applyingRemote||conflict.active)return;markLocalDraft();saveStatus.value='待同步';clearTimeout(changeTimer);changeTimer=setTimeout(async()=>{if(connected.value&&socket?.sendDocumentUpdate(content.value,revision.value))saveStatus.value='同步中';else await handleSave()},650)}
function handleCrdtChange(html){content.value=sanitizeHtml(html)}
function handleCrdtStatus(event){const status=typeof event==='string'?event:event.status;Object.assign(crdtReliability,typeof event==='object'?event:{});connected.value=status==='connected'||status==='synced';saveStatus.value=status==='synced'?(crdtReliability.pending?`待同步 ${crdtReliability.pending}`:'已同步'):status==='connected'?(crdtReliability.pending?`待同步 ${crdtReliability.pending}`:'同步中'):status==='unauthorized'?'无协作权限':status==='disconnected'?'离线':'重连中'}
async function handleSave(){clearTimeout(changeTimer);if(!editorReady||(!isCrdt.value&&conflict.active))return false;if(!hasUnsaved.value){saveStatus.value=isCrdt.value?(connected.value?'已同步':'离线保存'):'已保存';clearDraft();return true}saveStatus.value='保存中';try{const payload=isCrdt.value?{title:docTitle.value}:{title:docTitle.value,content:content.value,contentFormat:contentFormat.value,revision:revision.value};const response=await docApi.update(docId.value,payload);docTitle.value=response.data.title;acceptedTitle.value=docTitle.value;docStore.rememberUpdatedDoc(response.data);if(!isCrdt.value)applyDocument(response.data);saveStatus.value=isCrdt.value?'已同步':'已保存';clearDraft();return true}catch(exception){if(!isCrdt.value&&exception.code===409)await prepareConflict();else{error(exception.message||'保存失败');saveStatus.value='保存失败'}return false}}
const saveTitleIfChanged=()=>docTitle.value!==acceptedTitle.value?handleSave():null; async function prepareConflict(){try{const localContent=content.value,localTitle=docTitle.value;const response=await docApi.detail(docId.value);Object.assign(conflict,{active:true,localContent,localTitle,remote:response.data});warning('文档已更新，请选择冲突处理方式')}catch{error('无法获取最新文档')}}
function useRemoteVersion(){applyDocument(conflict.remote);conflict.active=false;clearDraft()} async function retryLocalVersion(){revision.value=conflict.remote.revision;content.value=conflict.localContent;docTitle.value=conflict.localTitle;conflict.active=false;await handleSave()}
async function switchFormat(format){if(isCrdt.value||format===contentFormat.value)return;const target=format==='HTML'?'富文本':'Markdown';if(!(await confirmDialog(`将当前内容转换为 ${target} 格式？复杂样式可能会有简化。`,{title:'切换编辑格式',confirmText:'转换'})))return;content.value=format==='HTML'?markdownToHtml(content.value):htmlToMarkdown(content.value);contentFormat.value=format;markLocalDraft();await handleSave()}
function togglePanel(panel){activePanel.value=activePanel.value===panel?'':panel} function replaceOne(){if(isCrdt.value){crdtEditor.value?.replaceText(searchForm.query,searchForm.replacement,false);return}if(!searchForm.query||!content.value.includes(searchForm.query))return;content.value=content.value.replace(searchForm.query,searchForm.replacement);handleContentChange()} function replaceAll(){if(isCrdt.value){crdtEditor.value?.replaceText(searchForm.query,searchForm.replacement,true);return}if(!searchForm.query)return;content.value=content.value.split(searchForm.query).join(searchForm.replacement);handleContentChange()}
function startPanelResize(event){if(window.innerWidth<=1100)return;event.preventDefault();panelResizeHandler=movePanelResize;panelResizeEndHandler=stopPanelResize;document.body.classList.add('resizing-panel');window.addEventListener('pointermove',panelResizeHandler);window.addEventListener('pointerup',panelResizeEndHandler,{once:true})}
function movePanelResize(event){const maximum=Math.max(280,window.innerWidth-360);panelWidth.value=Math.min(maximum,Math.max(240,window.innerWidth-event.clientX))}
function stopPanelResize(){if(panelResizeHandler)window.removeEventListener('pointermove',panelResizeHandler);if(panelResizeEndHandler)window.removeEventListener('pointerup',panelResizeEndHandler);panelResizeHandler=null;panelResizeEndHandler=null;document.body.classList.remove('resizing-panel')}
function scrollToHeading(index){if(isCrdt.value&&crdtEditor.value?.focusHeading(index))return;const headings=document.querySelectorAll('.editor-container h1,.editor-container h2,.editor-container h3,.editor-container h4,.editor-container h5,.editor-container h6');headings[index]?.scrollIntoView({behavior:'smooth',block:'center'})}
function toggleOutlineHeading(index){crdtEditor.value?.toggleHeading(index)}
async function loadCheckpoint(){panelLoading.value=true;try{const [status,history]=await Promise.all([crdtApi.checkpointStatus(docId.value),crdtApi.checkpointHistory(docId.value)]);Object.assign(checkpointInfo,status.data||{});checkpointHistory.value=history.data?.items||[]}catch(exception){error(exception.message||'协作恢复点加载失败')}finally{panelLoading.value=false}}
const checkpointReason=reason=>({MANUAL:'手动创建',SCHEDULED:'定时保存',THRESHOLD:'修改数量达到上限',RESTORE:'恢复历史状态'}[reason]||'系统自动保存')
async function createCheckpoint(){if(!(await confirmDialog('立即整理当前协作数据，并创建一个可恢复的安全点？',{title:'创建协作恢复点',confirmText:'立即创建'})))return;panelLoading.value=true;try{const response=await crdtApi.createCheckpoint(docId.value);Object.assign(checkpointInfo,response.data||{});await loadCheckpoint();success('协作恢复点已创建并验证成功')}catch(exception){error(exception.message||'协作恢复点创建失败')}finally{panelLoading.value=false}}
async function restoreCheckpoint(item){if(!(await confirmDialog(`恢复到 ${formatDate(item.createdAt)} 的协作状态？当前连接会短暂断开，并用该时间点的内容替换当前内容。`,{title:'恢复历史协作状态',confirmText:'确认恢复',danger:true})))return;panelLoading.value=true;try{await crdtApi.restoreCheckpoint(docId.value,item.id);success('历史协作状态已恢复，正在重新连接文档');setTimeout(()=>location.reload(),400)}catch(exception){error(exception.message||'历史协作状态恢复失败')}finally{panelLoading.value=false}}
function handleShortcut(event){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();event.shiftKey&&!isCrdt.value?handleSaveVersion():handleSave()}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='f'){event.preventDefault();activePanel.value='search'}} function handleBeforeUnload(event){if(hasUnsaved.value){event.preventDefault();event.returnValue=''}}
const draftKey=()=>`docflow:draft:${docId.value}`;function readDraft(){try{return JSON.parse(localStorage.getItem(draftKey())||'null')}catch{return null}}function clearDraft(){localStorage.removeItem(draftKey())}
async function handleUploadImages(files,callback){try{const urls=[];for(const file of files){const response=await fileApi.uploadImage(file);urls.push(response.data.url)}callback(urls);success('图片上传成功')}catch(exception){error(exception.message||'图片上传失败')}}
function handleEditorDrop(event){if(contentFormat.value!=='MARKDOWN')return;const files=[...(event.dataTransfer?.files||[])].filter(file=>file.type.startsWith('image/'));if(!files.length)return;event.preventDefault();handleUploadImages(files,urls=>{content.value+=urls.map(url=>`\n![](${url})\n`).join('');handleContentChange()})} function handleEditorPaste(event){if(contentFormat.value!=='MARKDOWN')return;const files=[...(event.clipboardData?.files||[])].filter(file=>file.type.startsWith('image/'));if(!files.length)return;event.preventDefault();handleUploadImages(files,urls=>{content.value+=urls.map(url=>`\n![](${url})\n`).join('');handleContentChange()})}
async function loadAttachments(){panelLoading.value=true;try{const response=await attachmentApi.list(docId.value);attachments.value=response.data||[]}catch(exception){error(exception.message||'附件加载失败')}finally{panelLoading.value=false}} async function uploadAttachments(event){const files=[...(event.target.files||[])];event.target.value='';for(const file of files){try{await attachmentApi.upload(docId.value,file)}catch(exception){error(`${file.name} 上传失败：${exception.message||''}`)}}await loadAttachments()} async function removeAttachment(item){if(!(await confirmDialog(`删除附件“${item.originalName}”？`,{title:'删除附件',confirmText:'删除',danger:true})))return;try{await attachmentApi.remove(docId.value,item.id);attachments.value=attachments.value.filter(a=>a.id!==item.id);success('附件已删除')}catch(exception){error(exception.message||'删除失败')}}
async function loadTags(){try{const response=await tagApi.forDocument(docId.value);metadata.tags=(response.data||[]).map(tag=>tag.name).join(', ')}catch{metadata.tags=''}} async function saveMetadata(){try{const response=await docApi.update(docId.value,{category:metadata.category});if(docData.value)Object.assign(docData.value,response.data);await tagApi.setForDocument(docId.value,metadata.tags.split(/[,，]/).map(x=>x.trim()).filter(Boolean));success('文档信息已保存')}catch(exception){error(exception.message||'保存失败')}} async function saveAsTemplate(){const name=await promptDialog('保存为模板',docTitle.value,{message:'请输入模板名称。',placeholder:'模板名称',confirmText:'保存'});if(!name?.trim())return;try{await templateApi.create({name:name.trim(),description:`来自文档：${docTitle.value}`,category:metadata.category||null,content:content.value,contentFormat:contentFormat.value});success('已保存为模板')}catch(exception){error(exception.message||'模板保存失败')}}
async function changePageFormat(format){if(!['A4','LETTER'].includes(format)||format===pageSettings.pageFormat)return;const previous=pageSettings.pageFormat;pageSettings.pageFormat=format;try{const response=await docApi.update(docId.value,{pageFormat:format});if(docData.value)Object.assign(docData.value,response.data);success(`页面已切换为 ${format==='LETTER'?'Letter':'A4'}`)}catch(exception){pageSettings.pageFormat=previous;error(exception.message||'页面大小切换失败')}}
async function savePageSettings(settings){const previous={...pageSettings};Object.assign(pageSettings,settings);try{const response=await docApi.update(docId.value,settings);if(docData.value)Object.assign(docData.value,response.data);success('页面设置已保存')}catch(exception){Object.assign(pageSettings,previous);error(exception.message||'页面设置保存失败')}}
async function loadVersions(){panelLoading.value=true;try{const response=await versionApi.list(docId.value);versions.value=response.data||[]}catch(exception){error(exception.message||'版本加载失败')}finally{panelLoading.value=false}}
async function handleSaveVersion(){if(!(await handleSave()))return;const name=await promptDialog('保存历史版本',`版本 ${versions.value.length+1}`,{message:'为这次保存设置一个易于识别的名称。',confirmText:'下一步'});if(name===null)return;const description=await promptDialog('添加版本说明','',{message:'可选：简要说明这个版本修改了什么。',multiline:true,confirmText:'保存版本'});if(description===null)return;try{await versionApi.save(docId.value,{content:isCrdt.value?currentEditorHtml():null,name:name.trim()||null,description:description.trim()||null});success('历史版本已保存');await loadVersions()}catch(exception){error(exception.message||'版本保存失败')}}
async function previewVersion(version){const response=await versionApi.detail(docId.value,version.versionNum);preview.version=response.data;preview.open=true}
async function compareVersion(version){compareSelection.value.push(version);compareSelection.value=[...new Map(compareSelection.value.map(item=>[item.id,item])).values()].slice(-2);if(compareSelection.value.length<2)return;try{const selected=[...compareSelection.value].sort((a,b)=>Number(a.versionNum)-Number(b.versionNum));const [older,newer]=await Promise.all(selected.map(item=>versionApi.detail(docId.value,item.versionNum)));comparison.title=`v${older.data.versionNum} 与 v${newer.data.versionNum} 对比`;comparison.olderLabel=`较早版本 · v${older.data.versionNum}`;comparison.newerLabel=`较新版本 · v${newer.data.versionNum}`;comparison.rows=buildSideBySideDiff(plainVersionText(older.data),plainVersionText(newer.data));comparison.open=true}catch(exception){error(exception.message||'版本对比失败')}finally{compareSelection.value=[]}}
function plainVersionText(version){if(version.contentFormat!=='HTML')return version.content||'';const html=sanitizeHtml(version.content||'').replace(/<br\s*\/?\s*>/gi,'\n').replace(/<\/(p|h[1-6]|li|blockquote|pre|tr|table)>/gi,'</$1>\n');const root=document.createElement('div');root.innerHTML=html;return (root.textContent||'').replace(/\u00a0/g,' ').replace(/\n{3,}/g,'\n\n').trimEnd()}
function changedParts(before,after){before=before??'';after=after??'';let prefix=0;const limit=Math.min(before.length,after.length);while(prefix<limit&&before[prefix]===after[prefix])prefix++;let suffix=0;while(suffix<limit-prefix&&before[before.length-1-suffix]===after[after.length-1-suffix])suffix++;const parts=(value)=>{const result=[];if(prefix)result.push({text:value.slice(0,prefix),changed:false});const end=suffix?value.length-suffix:value.length;if(end>prefix)result.push({text:value.slice(prefix,end),changed:true});if(suffix)result.push({text:value.slice(value.length-suffix),changed:false});return result.length?result:[{text:' ',changed:value.length===0}]};return [parts(before),parts(after)]}
function buildSideBySideDiff(before,after){const oldLines=before.split(/\r?\n/),newLines=after.split(/\r?\n/),rows=[];let oldIndex=0,newIndex=0,oldNumber=1,newNumber=1;const addRow=(oldLine,newLine,type)=>{const [oldParts,newParts]=changedParts(oldLine,newLine);rows.push({type,oldNumber:oldLine==null?null:oldNumber++,newNumber:newLine==null?null:newNumber++,oldParts:oldLine==null?[]:oldParts,newParts:newLine==null?[]:newParts})};while(oldIndex<oldLines.length||newIndex<newLines.length){const oldLine=oldLines[oldIndex],newLine=newLines[newIndex];if(oldLine===newLine){addRow(oldLine??'',newLine??'','same');oldIndex++;newIndex++;continue}let oldMatch=-1,newMatch=-1;for(let look=1;look<=12;look++){if(oldMatch<0&&newIndex+look<newLines.length&&oldLine===newLines[newIndex+look])oldMatch=look;if(newMatch<0&&oldIndex+look<oldLines.length&&newLine===oldLines[oldIndex+look])newMatch=look}if(oldMatch>0&&(newMatch<0||oldMatch<=newMatch)){for(let count=0;count<oldMatch;count++){addRow(null,newLines[newIndex++],'added')}continue}if(newMatch>0){for(let count=0;count<newMatch;count++){addRow(oldLines[oldIndex++],null,'removed')}continue}addRow(oldLine??null,newLine??null,'changed');if(oldIndex<oldLines.length)oldIndex++;if(newIndex<newLines.length)newIndex++}return rows}
async function rollbackVersion(version){if(!(await confirmDialog(`恢复到版本 v${version.versionNum}？当前内容会作为新修改被替换。`,{title:'恢复历史版本',confirmText:'确认恢复',danger:true})))return;try{const response=await versionApi.rollback(docId.value,version.versionNum);if(isCrdt.value){docTitle.value=response.data.title||docTitle.value;acceptedTitle.value=docTitle.value;content.value=sanitizeHtml(response.data.content||'');crdtEditor.value?.setContent(content.value);if(docData.value)Object.assign(docData.value,response.data)}else applyDocument(response.data);success('文档已恢复，恢复内容将作为新的协作修改同步')}catch(exception){error(exception.message||'恢复版本失败')}}
async function handleDeleteVersions(){if(!(await confirmDialog('清空全部版本历史？清空后无法恢复。',{title:'清空版本历史',confirmText:'全部清空',danger:true})))return;try{await versionApi.deleteAll(docId.value);versions.value=[];success('版本历史已清空')}catch(exception){error(exception.message||'版本历史清空失败')}}

async function loadComments(){panelLoading.value=true;try{const response=await commentApi.list(docId.value);comments.value=response.data||[]}catch(exception){error(exception.message||'批注加载失败')}finally{panelLoading.value=false}}
async function openCommentThread(commentId){
  activeCommentId.value=Number(commentId)
  commentFilter.value='ALL'
  activePanel.value='comments'
  await loadComments()
  await nextTick()
  document.querySelector(`[data-comment-thread-id="${activeCommentId.value}"]`)?.scrollIntoView({behavior:'smooth',block:'center'})
}
function activateCommentThread(thread){activeCommentId.value=thread.id;crdtEditor.value?.focusComment(thread.id)}
function openCommentDialog(selectedText=''){Object.assign(commentDialog,{open:true,parentId:null,selectedText:selectedText||'',content:''})}
function replyComment(thread){Object.assign(commentDialog,{open:true,parentId:thread.id,selectedText:thread.selectedText||'',content:''})}
function closeCommentDialog(){Object.assign(commentDialog,{open:false,parentId:null,selectedText:'',content:''})}
async function submitCommentDialog(){if(!commentDialog.content.trim())return;try{const payload={content:commentDialog.content.trim(),parentId:commentDialog.parentId||undefined,selectedText:commentDialog.parentId?undefined:commentDialog.selectedText};const response=await commentApi.create(docId.value,payload);if(commentDialog.parentId){comments.value.push(response.data);success('回复已发送')}else{if(!crdtEditor.value?.addComment(response.data.id))warning('批注已创建，但原选区已失效，请删除后重新选择文字');comments.value.unshift(response.data);activePanel.value='comments';success('批注已添加')}closeCommentDialog()}catch(exception){error(exception.message||(commentDialog.parentId?'回复失败':'批注添加失败'))}}
async function toggleCommentStatus(item){
  const resolved=item.status!=='RESOLVED'
  try{
    const response=await commentApi.setResolved(docId.value,item.id,resolved)
    Object.assign(item,response.data||{},{status:resolved?'RESOLVED':'OPEN'})
    selectedCommentIds.value=selectedCommentIds.value.filter(id=>id!==item.id)
    success(resolved?'批注已解决':'批注已重新打开')
  }catch(exception){error(exception.message||'批注状态更新失败')}
}
function removeComment(item){Object.assign(deleteCommentDialog,{open:true,item,busy:false})}
function closeDeleteCommentDialog(){if(deleteCommentDialog.busy)return;deleteCommentDialog.open=false;deleteCommentDialog.item=null}
async function confirmRemoveComment(){
  const item=deleteCommentDialog.item
  if(!item)return
  deleteCommentDialog.busy=true
  try{
    await commentApi.remove(docId.value,item.id)
    crdtEditor.value?.removeComment(item.id)
    comments.value=comments.value.filter(comment=>comment.id!==item.id&&comment.parentId!==item.id)
    if(activeCommentId.value===item.id)activeCommentId.value=null
    deleteCommentDialog.open=false;deleteCommentDialog.item=null
    success('批注已删除')
  }catch(exception){error(exception.message||'批注删除失败')}
  finally{deleteCommentDialog.busy=false}
}
async function resolveSelectedComments(){try{await commentApi.resolveBatch(docId.value,selectedCommentIds.value,true);comments.value.forEach(item=>{if(selectedCommentIds.value.includes(item.id))item.status='RESOLVED'});selectedCommentIds.value=[];success('所选批注已解决')}catch(exception){error(exception.message||'批量处理失败')}}

function currentEditorHtml(){return isCrdt.value?(crdtEditor.value?.getHtml()||content.value):(contentFormat.value==='HTML'?content.value:markdownToHtml(content.value))}
function renderedEditorHtml(){return document.querySelector('.editor-container .tiptap')?.innerHTML||currentEditorHtml()}
function exportFileName(extension){const name=(docTitle.value||'document').replace(/[\\/:*?"<>|]/g,'_').trim()||'document';return `${name}.${extension}`}
function downloadBlob(blob,fileName){const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=fileName;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function htmlDocument(body){const letter=pageSettings.pageFormat==='LETTER',cover=docData.value?.coverImage?`<img class="document-export-cover" src="${escapeHtml(docData.value.coverImage)}" alt="">`:'';return `<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><title>${escapeHtml(docTitle.value||'文档')}</title><style>@page{size:${letter?'Letter':'A4'};margin:${pageSettings.marginTop}mm ${pageSettings.marginRight}mm ${pageSettings.marginBottom}mm ${pageSettings.marginLeft}mm}@media screen{html{background:#e9eef4}body{box-sizing:border-box;width:${letter?'216':'210'}mm;min-height:${letter?'279':'297'}mm;margin:24px auto;padding:${pageSettings.marginTop}mm ${pageSettings.marginRight}mm ${pageSettings.marginBottom}mm ${pageSettings.marginLeft}mm;background:white;box-shadow:0 2px 12px #94a3b866}}@media print{body{margin:0;padding:0;box-shadow:none}}body{color:#1f2937;font-family:Arial,"Microsoft YaHei",sans-serif;line-height:1.75;overflow-wrap:anywhere}.print-header,.print-footer{color:#64748b;font-size:10px}.print-header{margin-bottom:10mm}.print-footer{margin-top:10mm;text-align:center}.document-export-cover{display:block;width:220px;max-height:145px;margin-bottom:18px;object-fit:cover}img{max-width:100%;height:auto}table{width:100%;border-collapse:collapse}th,td{padding:8px;border:1px solid #cbd5e1}pre{padding:12px;background:#111827;color:white;overflow:auto}.comment-highlight{background:#fef3c7;border-bottom:2px solid #f59e0b}.page-break{break-after:page;height:1px;border:0}[data-change-type='insert']{text-decoration:underline;color:#15803d}[data-change-type='delete']{text-decoration:line-through;color:#b91c1c}.katex-html{display:none}.katex-mathml{position:static!important;width:auto!important;height:auto!important;overflow:visible!important;clip:auto!important;white-space:normal!important}</style></head><body>${pageSettings.pageHeader?`<div class="print-header">${escapeHtml(pageSettings.pageHeader)}</div>`:''}${cover}<h1>${escapeHtml(docTitle.value||'无标题文档')}</h1>${body}${pageSettings.pageFooter?`<div class="print-footer">${escapeHtml(pageSettings.pageFooter)}</div>`:''}</body></html>`}
function escapeHtml(value){const node=document.createElement('div');node.textContent=value||'';return node.innerHTML}
function markdownWithFormulas(){const root=document.createElement('div');root.innerHTML=currentEditorHtml();root.querySelectorAll('[data-latex]').forEach(node=>{const latex=node.getAttribute('data-latex')||'';node.replaceWith(document.createTextNode(node.dataset.type==='block-math'?`\n\n$$${latex}$$\n\n`:`$${latex}$`))});return htmlToMarkdown(root.innerHTML)}
async function exportDocument(format){try{if(format==='docx'){const blob=await docApi.exportDocx(docId.value,currentEditorHtml());downloadBlob(blob,exportFileName('docx'));return}if(format==='pdf'){const blob=await docApi.exportPdf(docId.value,currentEditorHtml());downloadBlob(blob,exportFileName('pdf'));return}if(format==='html'){const offline=await buildOfflineHtml();downloadBlob(new Blob([offline],{type:'text/html;charset=utf-8'}),exportFileName('html'));return}if(format==='markdown'){downloadBlob(new Blob([markdownWithFormulas()],{type:'text/markdown;charset=utf-8'}),exportFileName('md'));return}const root=document.createElement('div');root.innerHTML=currentEditorHtml();root.querySelectorAll('[data-latex]').forEach(node=>node.textContent=node.getAttribute('data-latex')||'');downloadBlob(new Blob([root.textContent||''],{type:'text/plain;charset=utf-8'}),exportFileName('txt'))}catch(exception){error(exception.message||'导出失败')}}
async function buildOfflineHtml(){const parser=new DOMParser(),page=parser.parseFromString(htmlDocument(renderedEditorHtml()),'text/html');for(const image of page.querySelectorAll('img[src]')){try{const response=await fetch(new URL(image.getAttribute('src'),location.origin));if(!response.ok)throw new Error();const blob=await response.blob();image.src=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)})}catch{image.replaceWith(page.createTextNode(image.alt||'[图片不可用]'))}}page.querySelectorAll('.katex-html').forEach(node=>node.remove());return '<!doctype html>\n'+page.documentElement.outerHTML}
function openPrintPreview(){printPreview.html=htmlDocument(renderedEditorHtml());printPreview.open=true}
function printPreviewFrame(){printFrame.value?.contentWindow?.focus();printFrame.value?.contentWindow?.print()}
function printDocument(){openPrintPreview()}
async function createShare(){try{const response=await shareApi.create(docId.value,{permission:'READ',password:shareForm.password||null,expireTime:shareForm.expireTime?`${shareForm.expireTime}:00`:null});shareLink.value=`${location.origin}/share/${response.data.token}`;success('分享链接已生成')}catch(exception){error(exception.message||'分享失败')}} async function copyShareLink(){try{await navigator.clipboard.writeText(shareLink.value);success('链接已复制')}catch{error('复制失败')}}
async function loadCollaborators(){panelLoading.value=true;try{const response=await permissionApi.list(docId.value);collaborators.value=response.data||[]}catch{collaborators.value=[]}finally{panelLoading.value=false}} async function addCollaborator(){try{await permissionApi.add(docId.value,collaboratorForm);collaboratorForm.username='';await loadCollaborators()}catch(exception){error(exception.message||'添加失败')}} async function updateCollaborator(person,permission){try{await permissionApi.update(docId.value,person.userId,{permission});person.permission=permission}catch(exception){error(exception.message||'更新失败')}} async function removeCollaborator(person){if(!(await confirmDialog(`移除协作者“${person.username}”？移除后对方将无法继续访问此文档。`,{title:'移除协作者',confirmText:'移除',danger:true})))return;try{await permissionApi.remove(docId.value,person.userId);collaborators.value=collaborators.value.filter(item=>item.userId!==person.userId);success('协作者已移除')}catch(exception){error(exception.message||'移除协作者失败')}}
const versionLabel=type=>({AUTO:'自动',MANUAL:'手动',ROLLBACK:'回滚'}[type]||'自动'),formatTime=time=>time?dayjs(time).fromNow():'-',formatDate=time=>time?dayjs(time).format('YYYY-MM-DD HH:mm'):'-',formatBytes=size=>size<1024?`${size} B`:size<1048576?`${(size/1024).toFixed(1)} KB`:`${(size/1048576).toFixed(1)} MB`
